<script setup lang="ts">
import {computed,inject,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import type {UsageInsights,UsageInsightsParams,InsightGroup} from '@sodashitsu/protocol';
import {ConnectionKey,UsageInsightsPortKey} from '../injection.js';
import {useMachinesStore} from '../store/machines.js';
import {useUsageStore} from '../store/usage.js';
import {kindLabel} from './dashboardModel.js';
import {dateSlots,delta,exportInsights,limitForecast,limitWindows,rate,seriesPath,totalLabel,type LimitPoint} from './insightsModel.js';
const props=withDefaults(defineProps<{layout?:string;active?:boolean}>(),{layout:"overview",active:true});
const layout=computed(()=>props.layout);
const emit=defineEmits<{loaded:[range:{from:string;to:string}];insights:[params:UsageInsightsParams|null]} >();
const conn=inject(ConnectionKey,null),port=inject(UsageInsightsPortKey,null),machines=useMachinesStore(),usage=useUsageStore();
const today=()=>new Date().toISOString().slice(0,10),to=ref(today()),from=ref(new Date(Date.now()-29*86400000).toISOString().slice(0,10));
const kind=ref(''),model=ref(''),project=ref(''),account=ref(''),role=ref(''),zone=ref(Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'),machine=ref('current'),bucket=ref<'day'|'week'|'month'>('day');
const sessionFilter=ref(''),detailMachine=ref('');
const result=ref<UsageInsights|null>(null),peers=ref<{id:string;label:string;data:UsageInsights|null;error:string}[]>([]),busy=ref(false),error=ref(''),selectedSession=ref(''),filtersOpen=ref(false);
let lastReportSelection:UsageInsightsParams|null=null;
let disposed=false,epoch=0,lastKey='',timer:ReturnType<typeof setTimeout>|undefined;
const pending=()=>{if(timer)clearTimeout(timer);timer=undefined;};
onBeforeUnmount(()=>{disposed=true;epoch++;pending();});
watch(()=>machines.selectedId,()=>{epoch++;pending();lastReportSelection=null;emit('insights',null);sessionFilter.value='';selectedSession.value='';project.value='';account.value='';model.value='';machine.value='current';result.value=null;peers.value=[];history.clear();notified.clear();alerts.value=[];limits.value=[];busy.value=false;void load();});
async function fetchAt(id:string,params:UsageInsightsParams){
 let timeout:ReturnType<typeof setTimeout>|undefined;
 try{return await Promise.race([port?port(id,params):conn!.request('agent.usage_insights',params),new Promise<never>((_,reject)=>{timeout=setTimeout(()=>reject(new Error('timeout')),15000);})]);}finally{clearTimeout(timeout);}
}
async function load(refresh=false){
 if(!conn||busy.value||!props.active)return;emit('insights',null);pending();const version=++epoch;busy.value=true;error.value='';
 const params:UsageInsightsParams={from:from.value,to:to.value,timezone:zone.value,...(sessionFilter.value?{session:sessionFilter.value}:{}),...(kind.value?{kind:kind.value as 'claude'|'codex'}:{}),...(model.value?{model:model.value}:{}),...(project.value?{project:project.value}:{}),...(account.value?{account:account.value}:{}),...(role.value?{role:role.value as 'main'|'sub'|'unknown'}:{})};
 const key=JSON.stringify([machines.selectedId,machine.value,params]);if(!refresh||key!==lastKey){result.value=null;peers.value=[];detailMachine.value='';}lastKey=key;
 try{
  if(machine.value==='all'){
   const targets=machines.sections.filter(s=>s.id===machines.selectedId||machines.isSelectable(s.id));
   const values=await Promise.all(targets.map(async s=>{try{return {id:s.id,label:s.label,data:await fetchAt(s.id,params),error:''};}catch{return {id:s.id,label:s.label,data:null,error:'取得できません（未接続・未対応・タイムアウト）'};}}));
   if(disposed||version!==epoch)return;peers.value=values;const chosen=values.find(v=>v.id===machines.selectedId&&v.data)??values.find(v=>v.data);result.value=chosen?.data??null;detailMachine.value=chosen?.label??'';if(!result.value)throw new Error('all machines unavailable');
  }else{const value=await fetchAt(machine.value==='current'?machines.selectedId:machine.value,params);if(disposed||version!==epoch)return;result.value=value;peers.value=[];detailMachine.value=machines.sections.find(s=>s.id===(machine.value==='current'?machines.selectedId:machine.value))?.label??'選択PC';}
  emit('loaded',{from:params.from,to:params.to});lastReportSelection=machine.value==='current'||machine.value===machines.selectedId?params:null;emit('insights',lastReportSelection);
  if(result.value?.collecting||peers.value.some(p=>p.data?.collecting))timer=setTimeout(()=>void load(true),3000);
 }catch{if(!disposed&&version===epoch){result.value=null;peers.value=[];error.value='拡張分析を取得できませんでした。接続先の対応版、日付、タイムゾーンを確認してください。';}}
 finally{if(!disposed&&version===epoch)busy.value=false;}
}
watch(()=>props.active,active=>{if(active)void load(true);else{pending();epoch++;busy.value=false;emit('insights',result.value?lastReportSelection:null);}});
onMounted(()=>void load());
function preset(days:number){to.value=today();from.value=new Date(Date.now()-(days-1)*86400000).toISOString().slice(0,10);void load();}
const change=computed(()=>result.value?delta(result.value.totals.total,result.value.previous.total):null);
const subRatio=computed(()=>{const r=result.value;if(!r)return null;const main=r.byRole.find(x=>x.key==='main')?.total??0,sub=r.byRole.find(x=>x.key==='sub')?.total??0;return rate(sub,main+sub);});
const cacheRatio=computed(()=>{const t=result.value?.totals;return t?rate(t.cacheRead,t.input+t.cacheRead):null;});
const maxDay=computed(()=>Math.max(1,...(result.value?.byDay??[]).map(r=>r.total),...(result.value?.previousByDay??[]).map(r=>r.total)));
const categories=computed(()=>{const map=new Map<string,number>();for(const t of (result.value?.tools??[]).filter(t=>!t.nested))map.set(t.category,(map.get(t.category)??0)+t.calls);return [...map].sort((a,b)=>b[1]-a[1]);});
const categoryName=(s:string)=>({shell:'シェル',file:'ファイル',search:'検索',mcp:'MCP',skill:'Skill',agent:'エージェント',other:'その他'}[s]??s);
const roleName=(s:string)=>({main:'メイン',sub:'サブエージェント',unknown:'区分未取得'}[s]??s);
const selected=computed(()=>result.value?.sessions.find(s=>s.key===selectedSession.value));
const limits=ref<{key:string;account:string;label:string;usedPct:number;resetsAt?:number;forecast:number|null}[]>([]),history=new Map<string,LimitPoint[]>(),notified=new Set<string>(),alerts=ref<string[]>([]),alertsOn=ref(false);
watch(()=>usage.accounts,accounts=>{
 const now=Date.now();limits.value=limitWindows(accounts).map(w=>{
  w.key=`${machines.selectedId}:${w.key}`;const old=history.get(w.key)??[],last=old.at(-1);
  const points=last&&(last.used>w.usedPct||last.reset!==w.resetsAt)?[]:old;
  if(!last||last.at<now-10000)points.push({at:now,used:w.usedPct,...(w.resetsAt!==undefined?{reset:w.resetsAt}:{})});
  history.set(w.key,points.slice(-120));const expired=w.stale===true||(w.resetsAt!==undefined&&w.resetsAt<=now);const forecast=expired?null:limitForecast(points,now),key=w.key+':'+w.resetsAt;
  if(alertsOn.value&&!expired&&!notified.has(key)&&(w.usedPct>=90||(forecast!==null&&forecast-now<3600000&&(!w.resetsAt||forecast<w.resetsAt)))){notified.add(key);alerts.value.push(`${w.account} ${w.label}：上限が近づいています`);}
  return {...w,forecast};
 });
},{immediate:true});
function download(format:'json'|'csv'){
 if(!result.value)return;const url=URL.createObjectURL(new Blob([exportInsights(result.value,format)],{type:format==='json'?'application/json':'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`soda-usage-${result.value.from}-${result.value.to}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
const currentAxis=computed(()=>result.value?dateSlots(result.value.from,result.value.to,result.value.timezone):[]);
const previousAxis=computed(()=>{const r=result.value;if(!r)return [];const start=Date.parse(r.from+'T00:00:00Z'),end=Date.parse(r.to+'T00:00:00Z'),length=end-start+86400000;return dateSlots(new Date(start-length).toISOString().slice(0,10),new Date(start-86400000).toISOString().slice(0,10),r.timezone);});
const sumRows=(rows:InsightGroup[])=>{const map=new Map<string,number|null>();for(const day of currentAxis.value){let key=day;if(bucket.value==='month')key=key.slice(0,7);if(bucket.value==='week'){const d=new Date(key+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));key=d.toISOString().slice(0,10);}const value=rows.find(row=>row.key===day)?.total;map.set(key,value===undefined?map.get(key)??null:(map.get(key)??0)+value);}return [...map].map(([key,total])=>({key,total}));};
const periods=computed(()=>sumRows(result.value?.byDay??[]));
function periodRole(key:string,role:string){
 const rows=(result.value?.byDayRole??[]).filter(r=>r.key.endsWith(':'+role)).map(r=>({...r,key:r.key.slice(0,10)}));return sumRows(rows).find(r=>r.key===key)?.total??0;
}
const parentGroups=computed(()=>{
 const rows=result.value?.sessions??[],parents=rows.filter(s=>!s.parent||!rows.some(p=>p.key===s.parent));
 return parents.slice(0,12).map(parent=>({parent,children:rows.filter(s=>s.parent===parent.key).slice(0,12)}));
});
const weekdayHeat=computed(()=>Array.from({length:24},(_,hour)=>({hour,total:result.value?.byHour.find(r=>Number(r.key)===hour)?.total??0})));
</script>
<template>
 <section class="insights" data-usage-insights aria-label="利用分析ダッシュボード">
  <div class="insights-heading"><div><span class="eyebrow">USAGE INTELLIGENCE</span><h2>エージェント利用の全体像</h2><p>消費の推移、委譲、ツール利用をひとつの画面で。</p></div></div>
  <div class="filter-toolbar"><button :aria-expanded="filtersOpen" @click="filtersOpen=!filtersOpen">期間・条件</button><span>{{ result?.from??from }} 〜 {{ result?.to??to }} UTC</span><button v-for="d in [7,30,90]" :key="d" :disabled="busy" @click="preset(d)">{{ d }}日</button></div>
  <form v-show="filtersOpen" class="insights-filters" @submit.prevent="load()">
   <label>開始<input v-model="from" type="date" :disabled="busy"/></label><label>終了<input v-model="to" type="date" :disabled="busy"/></label>
   <label>PC<select v-model="machine" :disabled="busy"><option value="current">現在のPC</option><option v-if="port" value="all">接続中の全PCを比較</option><option v-for="s in machines.sections" :key="s.id" :value="s.id">{{ s.label }}</option></select></label>
   <label>種類<select v-model="kind" :disabled="busy"><option value="">すべて</option><option value="claude">Claude Code</option><option value="codex">Codex</option></select></label>
   <label>モデル<select v-model="model" :disabled="busy"><option value="">すべて</option><option v-for="s in result?.options.models" :key="s">{{ s }}</option></select></label>
   <label>プロジェクト／WS<select v-model="project" :disabled="busy"><option value="">すべて</option><option v-for="s in result?.options.projects" :key="s.key" :value="s.key">{{ s.label }}</option></select></label>
   <label>設定単位<select v-model="account" :disabled="busy"><option value="">すべて</option><option v-for="s in result?.options.accounts" :key="s.key" :value="s.key">{{ s.label }}</option></select></label>
   <label>役割<select v-model="role" :disabled="busy"><option value="">すべて</option><option value="main">メイン</option><option value="sub">サブ</option><option value="unknown">未取得</option></select></label>
   <label>時刻<select v-model="zone" :disabled="busy"><option value="UTC">UTC</option><option :value="Intl.DateTimeFormat().resolvedOptions().timeZone">PCのローカル時刻</option></select></label>
   <button :disabled="busy" type="submit">{{ busy?'集計中…':'集計・更新' }}</button>
  </form>
  <p v-if="sessionFilter">セッション {{ sessionFilter.split(':').at(-1)?.slice(0,8) }} の分析 <button :disabled="busy" @click="sessionFilter='';load()">全セッションへ戻る</button></p>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="busy&&!result&&!error" role="status">記録を読み取っています…</p>
  <template v-if="result"><p v-if="result.coverage.every(c=>c.files===0)">対象のログを検出できませんでした。未取得を利用ゼロとは扱いません。</p>
   <div class="collection-state" role="status"><span :class="{'warning':result.partial}">{{ result.collecting?'● 続きを集計中':result.partial?'● 一部の記録':'● 読取済み' }}</span><span>対象PC {{ detailMachine }} · {{ new Date(result.asOf).toLocaleTimeString() }} 更新 · {{ result.from }}〜{{ result.to }} UTC · 表示 {{ result.timezone }}</span><button @click="download('csv')">セッションCSV</button><button @click="download('json')">JSON</button></div>
   <div class="insights-metrics"><article><span>期間の取得トークン</span><strong>{{ totalLabel(result.totals.total) }}</strong><small>{{ change===null?'前期間の比較値なし':`前期間比 ${change>=0?'+':''}${change.toFixed(1)}%` }}</small></article><article><span>サブエージェントの比率</span><strong>{{ subRatio===null?'—':subRatio+'%' }}</strong><small>役割を取得できたトークンのみ</small></article><article><span>ツール呼び出し</span><strong>{{ result.totals.tools.toLocaleString() }}</strong><small>結果取得 {{ rate(result.totals.knownResults,result.totals.tools)??'—' }}% · 失敗 {{ result.totals.errors }}</small></article><article><span>キャッシュ読取率</span><strong>{{ cacheRatio===null?'—':cacheRatio+'%' }}</strong><small>入力＋キャッシュ読取が分母 · 応答あたり {{ result.totals.calls?totalLabel(result.totals.total/result.totals.calls):'—' }} tok</small></article></div>
   <div v-if="peers.length" class="peer-cards"><article><h3>取得成功PCの合計</h3><strong>{{ totalLabel(peers.reduce((sum,p)=>sum+(p.data?.totals.total??0),0)) }}</strong><p>{{ peers.filter(p=>p.data).length }} / {{ peers.length }} PC · ログ複製の重複を含む単純合計</p></article><article v-for="peer in peers" :key="peer.id"><h3>{{ peer.label }}</h3><strong>{{ peer.data?totalLabel(peer.data.totals.total):'—' }}</strong><p>{{ peer.error||`${peer.data!.totals.tools} ツール呼び出し` }}</p></article><small>以下の詳細は現在のPC（取得不可なら最初の取得成功PC）。PC間でコピーされたログは重複するため、無条件に合算しません。</small></div>
   <div v-if="result.activity&&(result.activity.started+result.activity.completed+result.activity.aborted+result.activity.failed)>0" class="collection-state">記録された処理ターン：開始 {{ result.activity.started }} · 完了 {{ result.activity.completed }} · 中断 {{ result.activity.aborted }} · 失敗 {{ result.activity.failed }}<small>各イベントの期間内件数。成果品質やタスク達成率ではありません。</small></div>
   <div class="insights-grid" :class="layout">
    <article class="insight-card timeline"><div class="card-heading"><h3>利用推移</h3><select v-model="bucket"><option value="day">日別</option><option value="week">週別</option><option value="month">月別</option></select></div>
     <svg v-if="result.byDay.length" viewBox="0 0 640 190" role="img" aria-label="期間トークンと前期間の推移"><path v-for="y in [0,60,120,180]" :key="y" :d="`M0 ${y}H640`" class="gridline"/><path :d="seriesPath(result.previousByDay,maxDay,640,180,previousAxis)" class="previous-line"/><path :d="seriesPath(result.byDay,maxDay,640,180,currentAxis)" class="current-line"/><circle v-for="r in result.byDay" :key="r.key" :cx="currentAxis.length===1?320:Math.max(0,currentAxis.indexOf(r.key))/(currentAxis.length-1)*640" :cy="180-r.total/maxDay*180" r="4" class="current-point"><title>{{ r.key }}: {{ r.total.toLocaleString() }} tok</title></circle></svg><p v-else>この期間に取得できた記録がありません。</p>
     <div class="axis-labels"><span>{{ currentAxis[0] }}</span><span>{{ currentAxis.at(-1) }}</span></div><div class="chart-legend"><span>● 選択期間</span><span>┄ 前期間（同じ日数）</span></div>
     <div class="period-bars"><button v-for="p in periods" :key="p.key" :title="`${p.key}: ${p.total===null?'未取得':p.total.toLocaleString()} tok`" :aria-label="`${p.key}: ${p.total===null?'未取得':p.total.toLocaleString()} tok`" :style="{height:Math.max(3,(p.total??0)/Math.max(1,...periods.map(x=>x.total??0))*65)+'px',opacity:p.total===null?.2:1}"><i v-for="role in ['main','sub','unknown']" :key="role" :class="role" :style="{height:(p.total?periodRole(p.key,role)/p.total*100:0)+'%'}"/><span>{{ p.key }}</span></button></div>
     <small>記録がない日を利用ゼロとは扱いません。前期間はUTCで同じ日数。週・月の端は選択期間内のみ。</small>
    </article>
    <article class="insight-card roles"><h3>メインとサブエージェント</h3><div class="role-donut" :style="{'--sub':(subRatio??0)+'%'}"><div><strong>{{ subRatio===null?'—':subRatio+'%' }}</strong><small>サブの比率</small></div></div><div v-for="g in result.byRole" :key="g.key" class="mini-row"><span>{{ roleName(g.key) }}</span><strong>{{ totalLabel(g.total) }}</strong></div></article>
    <article class="insight-card"><h3>ツール利用の構成</h3><div v-for="[name,count] in categories" :key="name" class="bar-row"><span>{{ categoryName(name) }}</span><div class="bar-track"><i :style="{width:(rate(count,result.totals.tools)??0)+'%'}"/></div><strong>{{ rate(count,result.totals.tools)??0 }}%</strong></div><p v-if="!categories.length">取得できるツール呼び出しがありません。</p><details><summary>ツール・Skill・MCPの内訳</summary><div v-for="t in result.tools" :key="t.basis+t.name" class="tool-row"><strong>{{ t.name }}</strong><span>{{ t.calls }}回 · 成功 {{ t.success }} / 失敗 {{ t.failed }} / 結果未取得 {{ t.unknown }}</span><small>{{ t.nested?'コード内の記述から推定（実行を保証せず、利用率の分母から除外）':t.basis==='inferred'?'分類を推定（SKILL.mdの読取）':'直接記録' }}</small></div></details></article>
    <article class="insight-card"><h3>プロジェクト／ワークスペース別</h3><div v-for="g in result.byProject.slice(0,8)" :key="g.key" class="bar-row"><button @click="project=g.key;load()">{{ g.label }}</button><div class="bar-track"><i :style="{width:(rate(g.total,result.totals.total)??0)+'%'}"/></div><strong>{{ totalLabel(g.total) }}</strong></div><details><summary>種類・モデル・設定別</summary><div v-for="g in [...result.byKind,...result.byModel,...result.byAccount]" :key="g.key" class="mini-row"><span>{{ kindLabel(g.label) }}</span><strong>{{ totalLabel(g.total) }}</strong></div></details></article>
    <article class="insight-card parents"><h3>親子エージェントとセッション</h3><div class="parent-graph"><div v-for="group in parentGroups" :key="group.parent.key" class="parent-branch"><button class="session-node" @click="selectedSession=group.parent.key"><small>{{ roleName(group.parent.role) }}</small><strong>{{ kindLabel(group.parent.kind) }} / {{ group.parent.label }}</strong><span>{{ totalLabel(group.parent.total) }} tok</span></button><span v-if="group.children.length" class="connector" aria-hidden="true">→</span><div class="child-nodes"><button v-for="child in group.children" :key="child.key" class="session-node sub" @click="selectedSession=child.key"><strong>{{ child.label }}</strong><span>{{ totalLabel(child.total) }} tok · {{ child.tools }} ツール</span></button></div></div></div><details><summary>セッション一覧と詳細</summary><div class="session-map"><button v-for="s in result.sessions.slice(0,24)" :key="s.key" :class="['session-node',s.role,{selected:selectedSession===s.key}]" @click="selectedSession=s.key"><small>{{ s.parent?'↳ '+s.parent.split(':').at(-1)?.slice(0,8):roleName(s.role) }}</small><strong>{{ kindLabel(s.kind) }} / {{ s.label }}</strong><span>{{ totalLabel(s.total) }} tok · {{ s.tools }} ツール</span></button></div><small>親子関係が記録にない場合は未取得。上位24件を表示。</small></details>
     <div v-if="selected" class="session-detail"><h4>{{ kindLabel(selected.kind) }} / {{ selected.label }}</h4><button :disabled="busy" @click="sessionFilter=selected.key;load()">このセッションの推移・モデル・ツールを分析</button><p>{{ selected.project }} · {{ selected.account }} · {{ roleName(selected.role) }}</p><p>入力 {{ selected.input.toLocaleString() }} / 出力 {{ selected.output.toLocaleString() }} / キャッシュ {{ selected.cacheRead.toLocaleString() }}</p><p>呼び出し {{ selected.calls }} · ツール {{ selected.tools }} · 結果取得 {{ selected.knownResults }} · 失敗 {{ selected.errors }}</p><p>{{ new Date(selected.firstAt).toLocaleString() }} 〜 {{ new Date(selected.lastAt).toLocaleString() }}</p></div>
    </article>
    <article class="insight-card"><h3>利用が集中する時間帯</h3><div class="hour-heat"><div v-for="h in weekdayHeat" :key="h.hour" :style="{opacity:.25+.75*h.total/Math.max(1,...weekdayHeat.map(x=>x.total))}" :title="`${h.hour}時: ${h.total.toLocaleString()} tok`"><span>{{ h.hour }}</span><small>{{ totalLabel(h.total) }}</small></div></div><p>{{ result.timezone }} · 応答記録の時刻であり、作業時間ではありません。</p></article>
    <article v-if="machine==='current'||machine==='all'||machine===machines.selectedId" class="insight-card"><h3>利用制限と到達見込み</h3><p>現在接続しているPCの制限枠です。履歴のPC選択・期間フィルターとは別の観測です。</p><label><input v-model="alertsOn" type="checkbox"/>この画面で上限接近を知らせる</label><p v-for="alert in alerts" :key="alert" role="alert">{{ alert }}</p><div v-for="l in limits" :key="l.key" class="limit-row"><div class="mini-row"><span>{{ l.account }} / {{ l.label }}</span><strong>{{ l.usedPct }}%</strong></div><div class="bar-track"><i :style="{width:Math.min(100,l.usedPct)+'%'}"/></div><small>{{ l.forecast?`直近観測からの推定到達 ${new Date(l.forecast).toLocaleString()}`:'推定に必要な観測を収集中（1分以上・3観測以上）' }}</small></div><p v-if="!limits.length">制限の使用率は未取得です。</p><small>予測は画面表示中の同じ制限枠の観測から計算。リセット・値の減少で再計算します。</small></article>
   </div>
   <details class="coverage"><summary>取得範囲と欠損を確認</summary><p>最大400日分の数値記録を保存。設定単位は認証アカウントの同一性を保証しません。メイン／サブの合計は応答単位の記録から計算し、会計累計へ再加算しません。</p><div v-for="c in result.coverage" :key="c.kind"><h4>{{ kindLabel(c.kind) }}</h4><p>{{ c.files }}ファイル · 続き {{ c.pending }} · 読取不可 {{ c.missing }} · 不正／日時なし {{ c.invalid }} · 巨大行の除外 {{ c.oversized }}</p><p>取得済み {{ c.firstAt?new Date(c.firstAt).toLocaleString():'—' }} 〜 {{ c.lastAt?new Date(c.lastAt).toLocaleString():'—' }}</p></div><p>履歴分析はClaude Code・Codexに対応。他の種類の期間・ツール履歴は未対応で、0とは扱いません。記録のないツール結果や親子関係は未取得。作業の完了率・品質はトークン数から推定しません。</p></details>
